package com.mutang.xunxi;

import android.app.Activity;
import android.content.Intent;
import android.graphics.Typeface;
import android.net.Uri;
import android.os.Bundle;
import android.webkit.*;
import android.widget.*;
import android.view.*;
import org.jsoup.nodes.Entities;

public final class ReaderActivity extends Activity {
    WebView web;ProgressBar progress;TextView title,status,mode;String original,heading,pendingUrl,pendingName,pendingReferer;static final int SAVE_FILE=208;boolean active=true,website=false,webFailed=false;ArticleReader.Result extracted;
    int d(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle state){super.onCreate(state);original=getIntent().getStringExtra("url");heading=getIntent().getStringExtra("title");if(state!=null){pendingUrl=state.getString("pendingUrl");pendingName=state.getString("pendingName");pendingReferer=state.getString("pendingReferer");}if(!ArticleReader.webUrl(original)){finish();return;}
        getWindow().setStatusBarColor(MainActivity.BG);getWindow().setNavigationBarColor(MainActivity.CARD);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(MainActivity.BG);root.setOnApplyWindowInsetsListener((v,i)->{if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets b=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(b.left,b.top,b.right,b.bottom);}else v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(root);
        LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(d(14),d(10),d(14),d(12));TextView back=ReaderUi.button(this,"返回",false);back.setOnClickListener(v->finish());bar.addView(back,new LinearLayout.LayoutParams(-2,-2));title=new TextView(this);title.setText("阅读");title.setTextColor(MainActivity.TEXT);title.setTextSize(17);title.setTypeface(Typeface.create("sans-serif-medium",0));title.setGravity(Gravity.CENTER);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));mode=ReaderUi.button(this,"原网页",true);mode.setOnClickListener(v->{if(website&&extracted!=null)show(extracted);else webPage(original);});bar.addView(mode,new LinearLayout.LayoutParams(-2,-2));TextView source=ReaderUi.button(this,"↗",false);source.setContentDescription("在外部浏览器打开原文");source.setOnClickListener(v->external(website&&web!=null&&ArticleReader.webUrl(web.getUrl())?web.getUrl():original,false));LinearLayout.LayoutParams ext=new LinearLayout.LayoutParams(d(44),-2);ext.setMargins(d(6),0,0,0);bar.addView(source,ext);root.addView(bar);
        progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);root.addView(progress,new LinearLayout.LayoutParams(-1,d(3)));
        status=new TextView(this);status.setText("正在提取正文…");status.setTextSize(14);status.setTextColor(MainActivity.MUTED);status.setGravity(Gravity.CENTER);status.setPadding(d(16),d(16),d(16),d(16));root.addView(status,new LinearLayout.LayoutParams(-1,-2));web=new WebView(this);web.setBackgroundColor(MainActivity.BG);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setDomStorageEnabled(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);if(android.os.Build.VERSION.SDK_INT>=26)settings.setSafeBrowsingEnabled(true);settings.setBuiltInZoomControls(true);settings.setDisplayZoomControls(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
        root.addView(web,new LinearLayout.LayoutParams(-1,0,1));
        if(ArticleReader.pdfUrl(original)){openPdf(original);finish();return;}
        new Thread(()->{try{ArticleReader.Result result=ArticleReader.read(original,heading);runOnUiThread(()->{if(!active||isFinishing())return;extracted=result;if(!website)show(result);else mode.setText("纯净阅读");});}catch(Exception e){runOnUiThread(()->{if(active&&!isFinishing()&&!website)webPage(original);});}},"xunji-reader").start();}
    void replaceWeb(boolean interactive){android.view.ViewGroup parent=(android.view.ViewGroup)web.getParent();int index=parent.indexOfChild(web);ViewGroup.LayoutParams lp=web.getLayoutParams();parent.removeView(web);web.stopLoading();web.destroy();web=new WebView(this);web.setBackgroundColor(MainActivity.BG);WebSettings s=web.getSettings();s.setJavaScriptEnabled(interactive);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setDomStorageEnabled(interactive);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setSupportMultipleWindows(false);if(android.os.Build.VERSION.SDK_INT>=26)s.setSafeBrowsingEnabled(true);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);parent.addView(web,index,lp);}
    void webPage(String url){if(!ArticleReader.webUrl(url))return;website=true;webFailed=false;title.setText("网页互动");mode.setText(extracted==null?"刷新网页":"纯净阅读");progress.setVisibility(View.VISIBLE);progress.setIndeterminate(true);status.setVisibility(View.VISIBLE);status.setText("原网站的点赞、评论和登录功能由网站自身提供");replaceWeb(true);WebView v=web;
        v.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String u=request.getUrl().toString();if(request.isForMainFrame()&&ArticleReader.pdfUrl(u)){openPdf(u);return true;}return !ArticleReader.webUrl(u);}@Override public void onPageFinished(WebView view,String u){if(web==view){progress.setVisibility(View.GONE);if(!webFailed)status.setVisibility(View.GONE);}}@Override public void onReceivedError(WebView view,WebResourceRequest req,WebResourceError error){if(web==view&&req.isForMainFrame())fail("网页加载失败，可重试或点击右上角 ↗ 打开原文。");}@Override public void onReceivedHttpError(WebView view,WebResourceRequest req,WebResourceResponse error){if(web==view&&req.isForMainFrame())fail("网站返回 HTTP "+error.getStatusCode()+"；可重试或打开原文。");}});v.setWebChromeClient(new WebChromeClient(){@Override public void onProgressChanged(WebView view,int p){if(web==view){progress.setIndeterminate(false);progress.setProgress(p);if(p==100)progress.setVisibility(View.GONE);}}});v.setDownloadListener((u,a,c,m,l)->{if(ArticleReader.webUrl(u)&&(ArticleReader.pdfUrl(u)||"application/pdf".equalsIgnoreCase(m))){openPdf(u);return;}if(ArticleReader.webUrl(u))new android.app.AlertDialog.Builder(this).setTitle("保存附件").setMessage("是否选择保存位置并下载此附件？").setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->saveFile(u,URLUtil.guessFileName(u,c,m),ArticleReader.fileType(URLUtil.guessFileName(u,c,m)),v.getUrl())).show();});v.loadUrl(url);}
    void fail(String message){webFailed=true;progress.setVisibility(View.GONE);status.setVisibility(View.VISIBLE);status.setText(message);}
    void show(ArticleReader.Result r){
        website=false;title.setText("阅读");mode.setText("原网页");replaceWeb(false);
        web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){
            String u=request.getUrl().toString();if(request.isForMainFrame()&&request.hasGesture()&&ArticleReader.webUrl(u)){ArticleReader.Attachment file=r.attachment(u);if(file!=null){if(file.pdf())openPdf(file.url);else saveFile(file.url,file.title,file.type,r.url);}else if(ArticleReader.pdfUrl(u))openPdf(u);else webPage(u);}return true;
        }});
        String name=heading==null||heading.trim().isEmpty()?r.title:heading;String safeTitle=Entities.escape(name==null?"":name);String host=Entities.escape(Collector.host(r.url));
        String css="*{box-sizing:border-box}body{background:#fff;color:#182830;font-family:sans-serif;font-size:16px;line-height:1.78;padding:20px;margin:0;overflow-wrap:anywhere;text-align:left}h1{font-size:25px;line-height:1.4;margin:5px 0 12px;letter-spacing:-.2px}h2{font-size:20px;line-height:1.45;margin:1.15em 0 .6em}h3,h4{line-height:1.45;margin:1em 0 .5em}p{margin:0 0 .82em;text-indent:0;text-align:left}p.reader-right,div.reader-right{text-align:right;margin-bottom:.45em}p.reader-center,div.reader-center{text-align:center}img{max-width:100%;height:auto;border-radius:9px;display:block;margin:8px auto}a{color:#126e65}blockquote{border-left:3px solid #126e65;padding-left:12px;margin:1em 0;color:#52636b}pre{white-space:pre-wrap;background:#e3f2ef;padding:12px;border-radius:10px}.reader-table{overflow-x:auto;max-width:100%;margin:.8em 0}table{border-collapse:collapse;min-width:100%;font-size:14px;line-height:1.55}td,th{border:1px solid #d6dfe0;padding:8px;vertical-align:middle}th{background:#f0f5f4}small{color:#697981}hr{border:0;border-top:1px solid #e7ecee;margin:17px 0}.reader-files{padding-top:2px;margin-top:23px;border-top:1px solid #e7ecee}.reader-files h2{font-size:18px;margin:16px 0 10px}.reader-file{display:flex;align-items:center;gap:12px;padding:13px;margin:0 0 10px;background:#f3f8f7;border:1px solid #e4eeec;border-radius:15px;text-decoration:none;color:#182830}.file-type{flex:0 0 42px;width:42px;height:46px;border-radius:10px;background:#dcefeb;color:#126e65;font-size:11px;display:flex;align-items:center;justify-content:center;font-weight:700}.file-copy{min-width:0;flex:1;display:flex;flex-direction:column;gap:5px}.file-copy strong{font-size:14px;line-height:1.46;font-weight:600;overflow-wrap:anywhere}.file-copy small{font-size:11px;color:#126e65}.file-arrow{font-size:24px;color:#126e65}.meta{font-size:12px;color:#697981;line-height:1.55}";
        String html="<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta http-equiv='Content-Security-Policy' content=\"default-src 'none'; img-src https: http:; style-src 'unsafe-inline';\"><style>"+css+"</style></head><body><h1>"+safeTitle+"</h1><div class='meta'>"+host+" · 应用内阅读"+(r.attachments.isEmpty()?"":" · 含 "+r.attachments.size()+" 个附件")+"</div><hr>"+r.html+"</body></html>";
        web.loadDataWithBaseURL(r.url,html,"text/html","UTF-8",null);progress.setVisibility(View.GONE);status.setVisibility(View.GONE);
    }
    void openPdf(String url){String ref=extracted!=null&&!website?extracted.url:web==null?original:web.getUrl();startActivity(new Intent(this,PdfActivity.class).putExtra("url",url).putExtra("referer",ref));}
    void saveFile(String url,String name,String type,String ref){
        if(!ArticleReader.webUrl(url))return;pendingUrl=url;pendingName=name==null||name.isEmpty()?"附件文件":name.replaceAll("[/\\\\:*?\"<>|]","_");pendingReferer=ref;
        String mime="application/octet-stream";if("docx".equals(type))mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document";else if("xlsx".equals(type))mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";else if("doc".equals(type))mime="application/msword";else if("xls".equals(type))mime="application/vnd.ms-excel";else if("txt".equals(type))mime="text/plain";else if("zip".equals(type))mime="application/zip";
        try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,pendingName),SAVE_FILE);}catch(Exception e){pendingUrl=null;Toast.makeText(this,"无法打开文件保存位置",Toast.LENGTH_SHORT).show();}
    }
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("pendingUrl",pendingUrl);state.putString("pendingName",pendingName);state.putString("pendingReferer",pendingReferer);}
    @Override protected void onActivityResult(int request,int result,Intent data){
        super.onActivityResult(request,result,data);if(request!=SAVE_FILE)return;String url=pendingUrl,ref=pendingReferer;pendingUrl=null;pendingName=null;pendingReferer=null;if(result!=RESULT_OK||data==null||data.getData()==null||!ArticleReader.webUrl(url))return;
        android.net.Uri destination=data.getData();android.app.ProgressDialog dlg=new android.app.ProgressDialog(this);dlg.setMessage("正在保存附件…");dlg.setCancelable(false);dlg.show();
        new Thread(()->{java.io.File temp=null;try{temp=java.io.File.createTempFile("attachment-",".tmp",getCacheDir());PdfActivity.download(url,temp,ref,48L*1024*1024);try(java.io.InputStream in=new java.io.FileInputStream(temp);java.io.OutputStream out=getContentResolver().openOutputStream(destination,"w")){if(out==null)throw new java.io.IOException();byte[] b=new byte[16384];int count;while((count=in.read(b))!=-1)out.write(b,0,count);}runOnUiThread(()->{if(active){dlg.dismiss();Toast.makeText(this,"附件已保存",Toast.LENGTH_LONG).show();}});}catch(Exception e){runOnUiThread(()->{if(active){dlg.dismiss();Toast.makeText(this,"下载或保存附件失败，请返回原网页重试",Toast.LENGTH_LONG).show();}});}finally{if(temp!=null)temp.delete();}},"xunji-attachment").start();
    }
    void external(String url,boolean close){if(!ArticleReader.webUrl(url))return;try{if(close)Toast.makeText(this,"无法在应用内读取，已打开原文",Toast.LENGTH_SHORT).show();startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));if(close)finish();}catch(Exception e){status.setVisibility(View.VISIBLE);status.setText("无法打开原文，请检查是否已安装浏览器。");}}
    @Override public void onBackPressed(){if(website&&web!=null&&web.canGoBack()){web.goBack();return;}if(website&&extracted!=null){show(extracted);return;}super.onBackPressed();}
    @Override protected void onDestroy(){active=false;if(web!=null){web.stopLoading();web.destroy();}super.onDestroy();}
}
